        Q("Ordered: metoprolol 25 mg. Stock: 50 mg tablets. How many tablets?", "Half a tablet", ["2 tablets", "1 tablet", "A quarter of a tablet"], "25 ÷ 50 = 0.5. Only halve tablets that are scored and safe to split."),
        Q("Ordered: amoxicillin 250 mg. Stock: 250 mg/5 mL. How many mL?", "5 mL", ["2.5 mL", "10 mL", "1 mL"], "250 ÷ 250 × 5 = 5 mL."),
        Q("Ordered: 75 mg. Stock: 50 mg/mL. How many mL?", "1.5 mL", ["0.67 mL", "2.5 mL", "15 mL"], "75 ÷ 50 × 1 = 1.5 mL."),
