        Q("Ordered: gentamicin 80 mg. Stock: 80 mg/2 mL. How many mL?", "2 mL", ["1 mL", "4 mL", "0.5 mL"], "80 ÷ 80 × 2 = 2 mL."),
        Q("Ordered: morphine 2 mg IV. Stock: 10 mg/mL. How many mL?", "0.2 mL", ["2 mL", "0.5 mL", "5 mL"], "2 ÷ 10 × 1 = 0.2 mL. Small volumes are where decimal slips happen."),
        Q("A 20 kg child needs paracetamol 15 mg/kg. What dose?", "300 mg", ["150 mg", "200 mg", "750 mg"], "15 × 20 = 300 mg."),
        Q("That 300 mg dose comes as a 120 mg/5 mL liquid. How many mL?", "12.5 mL", ["7.5 mL", "10 mL", "15 mL"], "300 ÷ 120 × 5 = 12.5 mL."),
