        Q("250 mL is to run over 30 minutes. What pump rate in mL/h?", "500 mL/h", ["250 mL/h", "125 mL/h", "750 mL/h"], "Rates are per hour: 250 mL in half an hour = 500 mL in an hour."),
        Q("1,000 mL over 8 hours through a giving set of 20 drops/mL. Roughly how many drops a minute?", "42", ["21", "125", "60"], "1,000 × 20 = 20,000 drops ÷ 480 minutes ≈ 41.7, so 42 drops a minute."),
        Q("How many mg of adrenaline are in 1 mL of a 1:1,000 solution?", "1 mg", ["0.1 mg", "10 mg", "0.01 mg"], "1:1,000 means 1 g in 1,000 mL, which is 1 mg/mL. 1:10,000 is 0.1 mg/mL."),
        Q("How many grams of glucose are in 1 litre of 5% glucose?", "50 g", ["5 g", "500 g", "0.5 g"], "Percent here means grams per 100 mL: 5 g per 100 mL, so 50 g per litre."),
        Q("Heparin: 25,000 units in 50 mL. Ordered: 1,000 units an hour. What rate?", "2 mL/h", ["20 mL/h", "1 mL/h", "4 mL/h"], "25,000 ÷ 50 = 500 units/mL. 1,000 ÷ 500 = 2 mL an hour."),
        Q("If the maximum dose of lidocaine is 3 mg/kg, how many mL of 1% lidocaine is that for a 70 kg adult?", "21 mL", ["2.1 mL", "210 mL", "7 mL"], "1% = 10 mg/mL. 3 × 70 = 210 mg. 210 ÷ 10 = 21 mL."),
        Q("Ordered: 5 microgram/kg/min for a 70 kg patient. Stock: 200 mg in 50 mL. What pump rate?", "5.25 mL/h", ["52.5 mL/h", "0.875 mL/h", "21 mL/h"], "5 × 70 = 350 microgram/min × 60 = 21,000 microgram/h. 200 mg/50 mL = 4,000 microgram/mL. 21,000 ÷ 4,000 = 5.25 mL/h."),
